  returnType?: number;
  /** 异常退货联系人 */
  returnContactInfoDto?: AliexpressAscpPoCreatePickupOrderContactInfoDTO;
  /** 预估揽收费用 */
  estimatedFee?: string;
  /** 预计揽收时间窗口-开始（yyyy-MM-dd HH:mm:ss），若商家填写需校验约揽时间切片有效性，即校验BY时间切片可用窗口期填写，平台会提供揽收可约时间日历查询接口，若查询异常情况或者无时间切片返回时，ISV不传值即可 */
